    (11, 5, "ጠሳጓቱ ፣ ጾሸነናፍሁት ፣ ኢንዳይል ፣ አቤቱ ፣ አምላኬ ፡፣ ?ያኝ ፡ ከማኝም።"),
    (11, 6, "የሚያስጨንቁኝም፡ ን\ኔ፡ ብናወጥ፣ደስ፡አንዳይላቸው ፣ እስከሞትም ፣ ኦንዳልተኛ ፣ ዓይኖቹን፥ አብራ።"),
