    (12, 1, "ቦ፣፡ ፣፡ በልቡ ፡ አሣዜሠአብሔር ፥ የለም ፡ ይላል ፣ በሥ'ራቸው ፣ ክሱ ፣ ’ስቈሉም በጎ ፣ ነገርን ፣ የሚሠራ ፣ የለምና።"),
    (12, 2, "የሚያስተው ል፡ አግዚአብሔርን ፡ የሚፈፌልግ፡ እንዳለ፡ ያይ ዘንድ Lr =i hh አሣዚስአብሔናር፡ ከሰማይ ፣ የስው ፡ ልጆችን፣ ተመለከተ።"),
