    (13, 5, "በአንደበቱ ፡ ሽንገላን ፣ የማይናገር ፤ በባልንጀራው ፡ ላይ ፣ ክፋትን ፣ የማያደርግ ፣ ዘመፉቹንም ፡ የማይስድብ።"),
