        15,
        3,
        "ሃፍቤን ፣ በሲቃል ፣ አቶተተዋችምና ፣ ቅዱስህንም ፣ በመቃብር ፡ አትተወውም # የሕይወትንኝ ፣ መንገድ ፣ አሳየኸኝ ፤ ) በፈትህ ፡ ባለው ፡ ችሮታሄ፡፣ Ad PORES i በቀኝህም።",
