    (15, 6, "ርይ ፡ ከፊትህ ፡ ይወጣ ፣ ዓይኖችህም ፣ በቅንነት ፥ ይመልከቱ።"),
    (
        15,
        7,
        'ልቤን ፣ ፈተንኸው ፡ በሌሊትም ፣ ጐብኘኽኝ ፣ ፈተንኽኝ ፣ ምክንያት ፡ አላገኘህብኝም የሰወን ፣ ሥራ ፣ አንደበቴ አንዳይናገር፡ ፈዎይ፣ ሃው ፣ ስለ፡ትእዛዝህ፡ቃል፡ጥብቅ ፡ የሆኑ ፣ ሕጎችን ፣ ጠበቅህ"።',
    ),
    (15, 8, "# አማግሮቼዉንዳይናወጡ አረማመጀኝ፣በመንገድህ፡አጽና።"),
