    (16, 7, "i 4H 5 ከክ ሳኦልና ፣ ከስላቶቹ ፡ ሁሉ ፣ አጩ ፣ ስለመዳኑ የኣግዘሠ ክብር አገልጋይ ፣ የዳዊት ፡ መዝሙር።"),
