    (17, 15, "በአርሱ ፣ ዘንድ ፡፣ ቅን ፡ ነበርዕሆ ፤ ከጋ.አቴም ፡ ተጠበቅሁ።"),
    (17, 16, "ስልዚህ እግዚአብሔር አንደ ፡ ጽድቁ ፡ አንደ ፡ እጄም ንጽሕና ፣ በዓይኖቹ ፣ ፊች ፡ መለሰልኝ።"),
