    (
        21,
        32,
        "አንተ ፣ የመድዳሂቴ ፣ ጸምላክ ፣ ነህና ፣ ጀ በጽድቅህ ፡ ምራኝ ፥ አስተምረኝም ፣ በዘመኑ ፣ ሁሉ ! አንቶን ፣ ተስፋ. ፡ አድርጌአለሁና ጾቤቱ ፣ ከጥንት ፣ ጀምሮ ፣ የነበሩትን ፣ 8 ምወረትህንና ፡ ቸርነትህን ፡ አስብ * የልጀጆነቴቱን ፡ ኃጢእትና ፡ መተላለፍ ፣ አታስብብኝ ፣ ፮ አቤቱ ፣ ስለ ፡ ቸርነትህ።",
    ),
    (22, 1, "ብዛች ፡ እንደ ፡ ምሕረትህ አስበኝ።"),
    (22, 2, "እግዚጾብሔጨሒ ፡ ቸር ፡ ቅንም ፡ ዛው ፣ ቿ፳ ስለዚዘ ፡ ኃጢጾተኛችን ፣ በመንገድ ፣ ይመራቸዋል።"),
