    (22, 6, 'እግዚጸብሔርን "የሚፈራ ፣፡ ስው ፡ ማን ፣ ነው ? ዘሚመርጠው ፡ መንገድ ፣ ይመራው ፣ ዘንድ።'),
    (23, 1, "ነፍሱ ፣፡ በመልካም ፡ ታድራለች ፡ ፲f ዘሩም ፡ ምድርን ፣ ይወርሳል።"),
