    (23, 5, "ጠላቶቹ ፣ አንደ ፡ በዙ ፣ አስተውል ፣ ih የግፍም ፣ ጥላቻ ፣ ጠልተወውኛል።"),
    (23, 6, "ነፍሴን ፣ ጠብቅና ፥ ዶድነኝ ፡ ጽ አንተን ፡ ታምኛለሁና ፣ አልፈር።"),
    (23, 7, "አንቶን ፡ ተስፋ ፡ አድርጌአለሁና ፡ ፳B የዋሃትና ፡ ቅንነት ፣ ይጤብቁኝ።"),
    (23, 8, "አቤቱ ፣ እስራኤልን ፣ ከመከራው ፣ ሆሉ ፣ አድነው።"),
    (23, 9, "ጽሹ፱ መገ ፣፳ s ስለ ፣ ትሩዳማ።"),
    (
        23,
        10,
        "ኣቤቱ ፣ እኔ ፣ በየዋሃቱ ፣ ሄጃለሁና ፣ ፍረድልኝ #h በእግዚአብጨርም አምኛለሁና ፡ አልናወጥም # አቤቱ ፣ ፍተነኝ ፡ መርምረኝም ! f ኵላሊቴንና ፡ ልቤን ፡ ፍዯን።",
    ),
    (24, 1, "ክርክቲያኘ ሃይ ኘኝ ትኝ ሥርኝች የዳዊት ፣ መዝሙር ፤ ፳፱ ፡ ፩፱።"),
    (24, 2, "ምሕረትህ ፡ ዘዓይኔ ፣ ፊት ፣ ነው ፡ በእወሣትህም ፣ ተመላለስሁ።"),
    (24, 3, "በከንቱ ፡ ሸንን ፣ አልተቀመጥሁም ፣ ከዓመፀኞችም ፣ ጋር ፡ አልተባበርኩም።"),
    (24, 4, "የክፉዎችን ፡ ማኅበር ፣ ላሆ ፣' ከዝንኑጉዎችም ፡ ጋር ፣ አልቀመጥም።"),
    (24, 5, "የምስጋናን ፣ ድምፅ ! ኣስማ ፣ ዘንድ ፣ አጆቹን ፡ ንጹሳሕ ፣ አይርጋኣሆ።"),
    (24, 6, "ተአምራትህንም ፣ ሁሉ ፣ አኢነግር ፣ ዘንድ ፣ አቤቱ ፣ መሠዊያህን ፣ ኣዘራልሆ።"),
    (24, 7, "አቤቱ ፣ የቤትህን ፡ ስፍራ።"),
    (24, 8, "የክብርህንም ፡ የማደሪያ ፥ ቦታ ፥ ወደድሁ።"),
    (24, 9, "ከኃጋጢአተኛች ፣ ጋር ፡ ሃፍቤን ፣ ከደም ፣ ሰዎችም ፡ ጋር ፡ ሕይወቴን ፣ አታጥፋ ፣ በእጃቸው ፡ ተንኰል ፣ አለባቸው ፣ ቀኛቸውም ፡ መማለጃ ፡ ተሞልታለች።"),
    (24, 10, ". እኔ ፣ ግን ፡ በየዋሃቱ ፡ ሄጃለሁ ፤ አድነኝ ፣ ማረኝም።"),
    (
        24,
        11,
        "እግሮቹ ፣ በቅን፣ት ፣ ቁመዋል ፤ አቤቱ ፣ በማሣዘር ፡ አመዘግንሃለሆሁ UO ከለ ፡ ሕዝቅያስ = አአ ብሔር ፣ ‘ብርሃኔና ፣ መድኃኒቱ ‘ነው የሚያስፈራኝ ፣ ምንድኝ ፡ ነው ? ኣሣማዚአብሒር ፡የሕይወቱ፣ መታመኛዋ ፣ ነውና ፣ የሚያስደነግጠኝ ፣ ምንድር ፣ ነው’።",
    ),
    (24, 12, 'ክፉዎች ! አስጨናቂቁዎች ፡ ጠላቶቹም ! ሥጋዬን ! ይበሉ ፣ ዘንድ ፣ በቀረቡ" ፣ ጊዜ ፣ እሃርሱ ፥ ቱተሰኛክለወው ፣ ወፉቁ።'),
    (
        24,
        13,
        "ጠላትም ፣ ቢከበኝ ፣ ልቤ፣ አይፈራ ፤ ሰልፍም ፡ ቢነሣብኝ ፡ በዚህ ፣ አእተማመናለሆ ፣ ኣግዚአብጨርን ፡ አንዲች ፣ ነገር ፣ ስመንሆች ፣ እርስዋንም እዛስሆ ፤ በሕይወቱ ዘመን ፣ ሆዬ።",
    ),
    (
        24,
        14,
        "በአግዚአብሔር ፡ ቤት ፣ እኖር ፣ ዘንድ ፣ እግዚክአብሇጨርን ፣ ደስ ፣ የሚያስሰኘወንም ፣ አይ፣ዘንድ መቅደሱንም ፣ አመለከት ፣ ዘንድ ፣ ነው = በመከራዬ ፣ ቀን ፣ በድንኳኑ ስወሮኛልና ፣ በድንኳኑም ፣ መሸሸጊያ ፣ ሸሽጎኛልና ፣ በአፉዶባባይም ፡ ከቱ ፣ ከፍ።",
    ),
    (
        24,
        15,
        "እነሆ ፣ አሁን ፡ በዙሪያ ፣ ባሉ ፣ በጠላቶቹ ፣ ላይ ፣ ራሴን ፣ ከፍ ፣ ክፍ ፣ ኣዶረን በድንኳኑም ፡ የምስጋና ፣ መሥዋዕትን ፣ ሠቸሆ፣፤ ለእግዚአብሔር ፡ እቀኛለሁ ፣ እዘምርለትማለሁ።",
    ),
    (24, 16, "አቤቱ ፣ ወደ ፣ አንተ ፡ የጮኩቫን ፣ቃያሱን ስማሣኝ 1 ማረኝ ፡ አድምጠኝም።"),
    (24, 17, "አንተ ፣ ፊቱን ፡ አሹት።"),
    (24, 18, "ብለኻዃልና ፣ አቤቱ ፣ ፊትህን ኣሻለሆ ፡ ልቤም ፣ አንተን ፣ አንተን ፣ አለ።"),
    (24, 19, "ፊትህን ፡ ኢኔ ፣ አታዙር ተቆጥተህ ፣ ከባሪያህ ፡ ፈቀቅ ፣ አችበል ፤ ረዳቾ ፣ ሁነኝ ፣ አትጣለኝም የመድኃኒቴም ፣ አምላክ ፣ ሆይ ፣ አችተወኝ።"),
    (24, 20, "አባቴና ፡ እናቴ ፡ ጥለውኝ ፣ ነበርና ፣ እግዚአብሔር ፣ ግን ፣ ተቀበለኝ።"),
    (24, 21, "አቤቱ ፣ መንገድህን • አስተምረኝ ስለ ፡ ጠላቶቼም ፡ በቀና ፣ መንገድ ፣ ምራኝ።"),
    (24, 22, "Le ፱ f ተ ጓርክቲያን ሃይማሃትና ሥርዓት TE i eR የሐሣ“ምስክሮችና፡ዓመፀኞች፡ትነሥተውብኛልና፣ ፲፪ ልፅወጻቶቹ ፡ ፈቃድ ፡ አሳልፈሄ ፣ አትስጠኝ።"),
    (
        25,
        1,
        "የግዜ ኣብሠጨርን ቾርኔች ፣ ዘሕያዋን፣ ምድር፡አይ፥ ዘንድ! አምናልሁ # እግዚአብሐርን ‘ስፋ ፣ ድርግ ! በርታ ‹ ልብህም ፣ ይጽና ! እግዘአብሔር ተስፉ ፣ አድርሣ።",
    ),
    (25, 2, "He #ች [i ስጻሕዝቅያስ።"),
    (25, 3, "አቤቱ ፡ ወደ፡አንተ፣ አጠራልሆ ፤ ዝም ፣ ብትለኝ ፣ ደ ፡ ኤድጓድ ፡ እን ደሚወርዱት ፡ እንዳልመስል አንተ ፣ አምላ ቱ ዝም ፣ አቸበለኝ።"),
    (25, 4, "ወደ ፡ መቐዴስህ ፡ ማደሪያ ፡ አጀን ፣ በነሣሆ፡፣ ጊዜ ፣ ወደ ፡ ኣን ፣የጮኽሆሁችን የልመናዬን ቃል ፣ ስማ።"),
