    (48, 4, 'YE SR ስለ፣፡ ራሱ! ክለሕዝቅያስና ፣ ስለመቃያብያን » ኣቱ ፣ እለ"ቱን ፣ አድምጥ ፣ ልመናዬንም ፡ ቸል ፡ አትበል።'),
