    (77, 1, "ጆሮህንም ፡ ወደ ፣ ጩኸቱ ፣ አዘንብል, ! ነፍሴ ፣ መከሪ'ን ፣ መግባ ለችና ሕይወቴም ፡ ወደ ፡ አል ፡ ቀርባለችና።"),
    (77, 2, "ድጓድ ፣ ከሚወርዳዱ፡ ፣ ጋር ፣ ተቆወርሆ' ፡ ረዳትም ፡ አንደሌለው ፣ ስወ ፣ ሆንሁ።"),
    (77, 3, "ልዘሳለም ፣ አንደማታስባቸው ፣ እኙደ ፣ ተገዶሱና ፣ በመቃብር ፣ ውስጥ።"),
    (77, 4, "አንደ ፣ ተጣሎ በሙታን ፣ ውጥ ፣ ኢንዳ ፣ የተጣልሁ ፥ ሆንሁ ! አነርሱም ፡፣ ከእጅህ ፣ ተልዩ።"),
    (77, 5, "በሞት ፣ ዋላ ፣ ውስጥ ፣ በታችኛው ፣ ጐድጓድ ፡ ክስዋመጥኽኝ።"),
    (
        77,
        6,
        "(ኣs ፣ ጳይ ፣ ምሦጣሄህ ፣ ጸና ፥ መቅሠፍችህን ፣ ሁሉ ፡ በአኔ ፣ ጻይ ፣ አመጣህ ዛ የሚያውቁኝን ፣ ከእኔ ፣ አራቅህ ! በኣገርሱ ፣ ዘንድ ፣ ርዙስ ፣ አደረግኸኝ ፣ ያዙኝ ፡ መውጫም ! አላጡኝ።",
    ),
    (77, 7, "ዓይኖቼም ፣ በመከራ ፡ ፈዘዙ ፣ አቤቱ ፣ ሆል ጊዜ ፡ ወደ ፣ አንተ ፣ ጮኸሆ።"),
    (77, 8, "እጆቹንም ፥ ወደ ፣ አንተ ፣ ዘረጋሆ።"),
    (
        77,
        9,
        "በወ'ኑ ፣ ሙታን ! ተጸጾምራት ፡ ታደርጋለህን ፣ የሞቱትስ ፡ ተነሥተው ፣ ያመሰስግኑሃልን ፣ በመቃብርስ ፣ ውስጥ ፣ ቸርነትህን ፥ አወሣትህንስ ፣ በጥፉ ፡ ስፍራ ፣ ይናገራሉን።",
    ),
    (
        77,
        10,
        "ተአምራትህ ፣ በጨለማ ፥ ጽድቅህም ፡ በመረሳት ፣ ምድር ፣ ትቸታወቃለችን ! ኣቤቱ ፣ ኣኔ ፣ ማግኘ ፣ ወደ ፣ አንታ ፣ ጮኽሁ ፥ ጧች ፣ ጸሎቴ ፡ ወደ ፡ ፈትህ ፣ ትዴርሳሌች።",
    ),
    (
        77,
        11,
        "ክፍቱ ፣ ሃፍሴን ፣ ልምን ፣ ትጥላለህ ? ፊቾህንስ ፣ ከአኔ ፥ ምን ፡ ችስወውራስሌህ ? አኔ ፣ ከታናሽነቴ ፣ ችግረኛ፡ ለሞትም፡ የቀረብሆ ፡ ነኝ ፥ ነ ሽፍ ፣ ክፍ፡ ካልሆ ፡ በኋላ፡ ግን፣፡ ተዋረድሆ፡ ተናቅሆም።",
    ),
    (77, 12, "መቅሠቹችህ ፡ በላዬ ፡ አለፈ ሣግርማህም ፣ አስደነገጠኝ * ሆል ፣ ጊዜ ፣ አንደ ፣ ውጋ ፣ ከበቡኝ ፣ በአንድነትም ፡ ያዙኝ።"),
    (77, 13, "ተ ክርስቲያን ሃይማኖትና ሥርዓት የዳዊት ! መዝሙር ፡ ፳፮፡#ፍ።"),
    (77, 14, "FEE ወዳጅንና ፣ በልንጀራዬን ፥ ፲# ዘመዶቼን , ከመከራ ፣ የተነሣ ፣ ከአኔ ! አራቅህ።"),
    (77, 15, "Rio ፤ iy tg ለ ፡ ትሩዳን።"),
    (77, 16, "ዞጾቤቹ፣ ምሕረትህን ፡ ለዘላለም ፣ እዘምራለሁ 8 እው፣ችህንም ፣ በአፌ ፣ ለልጅ ፡፣ ልጅ ፣ አናገራለሆ።"),
    (77, 17, "አንተ ፣ ምሕረት ፡ ለዛላለም ፣ ይመሠረታል ፣ ብለሃልና ፣ ፪ እውነትህም ፣ በሰማይ ፥ ይጸናል።"),
    (
        77,
        18,
        "ከመረጥሁት ፣ ጋር ! ቃል፡፣ ኪዳኔን ! አደረግሁ ፣ IN ለባሪያዬም ፡ ለዳዊት ፡፣ ማልሠሆ ፡ ዘርሀን ፣ ስዘላለም ፣ አዘጋጃለሁ ፣ ዙሆፋንሀንም ፡ ለልጅ ፡ ልጅ ፣ እመሠርታለሆ » አቤቱ ፣ ሰማያት ፣ ተአምራትህን ፣ ፳ እውነትህንም ደግሞ፣ በቅዱሳን፣ ማኅበር፡ያመሰግናሉ።",
    ),
    (
        77,
        19,
        "በስማይ የሚተካከስወ፡ ማን፣ነውገ፣ ፳ ከአማልክትስ፡ልጆች፣ ብሪ! ማን፣ይመስለዋል? በቅዱላኝ ፣ ምክር ፣ አግዚአብሔር ፡፣ ክቡር ፣ ነው ፣ በዙሪያው ፡፣ ባሉች ፡፣ ሁሆሉ፡ ላይ ፣ ታላቅና፡ግሩም ፣ ነው።",
    ),
    (77, 20, "የሠራዊት፡አምላክ፡ አንደ፤አንተ፡ ያለ፣ማን፣ሃው፣ ፳ጽ እቤቱ ፣ አንተ ፣ ብርቱ ፣ ነህ ፣ አውነትህሄም ፣ ይክብሃል።"),
    (77, 21, "የባሕርን ፣ ኃይል ፣ አንተ ፣ ትገዛለህ ፣ B የሞገዱንም ፣ መናወጥ ፣ አንተ ፣ ዝም ፣ ታሰኛዋለህ።"),
    (
        77,
        22,
        "አንተ • ትዕቢተኛውን ፣ አንደ፡ ጉገደለ፣ አዋረድኽኸው፣፥ ፲ በኃይልህም ፣ ክንድ ፡ ጠላቶችህን ፣ በተንሃቸው = ሰማያት ፡ የአንተ ፡ ናቸው ምድርም የአንተ ፣ ናት ፣፡ ፲፪ ዓጸምንና ፣ ሞላውንም ፣ አንተ ፡ መሠረትህ = ሰሜንንና ፡ ደቡብን ፡ አንተ ፡ ፈጠርህ ! TE ታቦርና ፣ አርሞንዔምም ፣ በስምህ ፣ ዴስ ፡ ይላቸዋል ፥ ክንድህ ፡ ከኅይልህ ፤ Py ነው ፣ ፲F እጅህ ፡ በረታች ፡ ቀኝህም ፡ ከፍ ፡ ከፍ ! አለች።",
    ),
    (77, 23, "የዙፋፉኘህ ፣ መሠረች ፡ የጽድቅ ፣ ፍርድ ፣ ሃው ፤ {8 ምሕረትና ፣ አውነት ፣ በፊትህ ፣ ይሄዳ።"),
    (77, 24, "የምስጋናን፡አልልፓ የሚያውቅ ፡መዝብ፡ምክኑጉን።"),
    (77, 25, "፣ው፣፡ ፲፪ አቤቱ ፣ በፊትህ , ብርሃን ፣ ይሄዳ # በቤምህ ፣ ቀኑን ፣ ሁሉ ፡ ደስ ፡ ይላቸዋል ፡ TE በጽድቅህም ፡ ከፍ ፡ ከፍ ፣ ይላሉ።"),
    (77, 26, "መመኪያ ፣ አንተ ፣ ነህና ፣ IE በሞግስህም ፣ ኃይላችን ፡ ከፍ ፡ ከፍ ፣ ይላልና።"),
    (77, 27, "ረድኤታችን ፡ ዘእግዚአብሔር ፡ ፲# ሽንጕጐሣችንም ፡ ከአስራኤል ፡ ቅዱስ ፡ ነወና።"),
    (
        77,
        28,
        "(በዚያ ፡ ጊዜ ፣ ለልጆችህ ፡ በራአይ ፣ ተናገርህ ፥ አንዲህም ፥ አልህ ፣ ረድኤቱን ፡ ቢጋያል፡ ጳይ፡አኖርሆ ፣ ከቁዝቬም ፣ የተመረጠውን ፣ ዩፍ ፣ ክፍ ፣ አይረሣግሆ።",
    ),
    (77, 29, "las ባሪያዬን ፡ ዳዊትን ፣ አግኘሆት ፣ ፳ ቅዱስ ፣ ዘይትንም ፡ ቀባሆት።"),
    (77, 30, "ኢጅም ፣ ቸረዳዋለች ፣ ጽ8 ክንዴም ፡ ታጸናዋልች።"),
    (77, 31, "ጻት ፣ በኣርዙ ፣ ጓይ ፣ አይበረታም #g የዓመፃ ፡ ፀአጅም ፣ መከራ ፡ አያድርስበትም።"),
    (
        77,
        32,
        "ጠጻቶቹን ፡ ከፊቱ ፣ አጠፋለሆ ! ፳፻ የሚመጠራትንም ፣ አዋርዳቸዋልሁ 5 እወማቴና ፡ ምሕረቴም ! ከአርሱ ፡ ጋር ፣ ነው ! ፳፱ በቤሜም ፥ ሥልጣኑ ፣ ዛፍ ፣ ኳፍ ፣ ይልል።",
    ),
    (77, 33, "አጅግ ፡ በባሕር ፡ ጓይ ፣ ፳ደ ቀኙንም ፣ በወንዞች ፣ ላይ ፣ አኖራለሁ።"),
    (77, 34, "እር ፣ አባቴና ፣ አምላኬ [iy የመድኃኒቴም ፣ መጠጊያ ፣ አንተ ! ነህ ይላል።"),
    (77, 35, "ክርስቲያኘ ሃይማኖትና ምርት የዳፍት , መዝሙር ፡ ጄድ = ZRF እኔም ፡ ደግሞ ፡ በዙሬ ፣ አደርገዋለሁ ከምድር ፣ ነገሥታትም ፣ ዙሉ ፣ ከፍ ፣ ይላል።"),
    (77, 36, "ለዘላለምም ፣ ምሕረቴን ፣ ለእርሱ ፣ አጠብቃለሆ ፣ ኪዳኔም ፣ በኣእርዙ ፥ ዘንድ ፣ የታመነ! ነው።"),
    (77, 37, "ዘሩንም ፡ ለዓለምና ፣ ለዘላለም ፣ አበዛለሁ ፣ ዙፋኑንም ፣ እንደ።"),
    (77, 38, "ስማይ ፥ ዘመን ፥ አደርጋለሁ።"),
    (77, 39, "ልጆቹ ፡ ግን ፡ ሕንን ፣ ቢተዉ ፣ በፍርይዴም ! በይሄዱ።"),
    (77, 40, "ሥርዓቴንም፡ ቢያረክሱ ፥ ችእዛዜንም ፣ ባይጠብቁ።"),
